fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Calculate rook moves
    // 0 moves if same square
    // 1 move if same row or same column
    // else 2 moves
    let rook_moves = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Helper to determine the color of a square: (row + col) mod 2
    // if colors differ, bishop cannot reach (0 moves)
    // if same square => 0 moves
    // if on the same diagonal => 1 move
    // else if reachable => 2 moves
    let same_color = (r1 + c1) % 2 == (r2 + c2) % 2;

    let bishop_moves = if r1 == r2 && c1 == c2 {
        0
    } else if !same_color {
        0
    } else if (r1 - r2).abs() == (c1 - c2).abs() {
        1
    } else {
        2
    };

    // King moves is the Chebyshev distance
    let king_moves = (r1 - r2).abs().max((c1 - c2).abs());

    vec![rook_moves, bishop_moves, king_moves]
}